import { GoogleGenAI } from "@google/genai";
import { ChatMessage } from "../types";

export const getGeminiResponse = async (history: ChatMessage[], message: string) => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || "" });
  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: [
        ...history.map(h => ({ role: h.role, parts: [{ text: h.text }] })),
        { role: 'user', parts: [{ text: message }] }
      ],
      config: {
        systemInstruction: `You are a professional video editing consultant for "CreativeEdit BD". 
        Your goal is to help users brainstorm video ideas, write scripts, and decide which editing style suits their needs.
        Always respond in Bengali (বাংলা) unless requested otherwise.
        Be polite, creative, and encouraging. 
        If a user asks about pricing, refer them to the website's pricing section but you can give rough estimates based on the provided rates:
        - Social Media: 500 BDT/min
        - Vlog: 1200 BDT/min
        - Advertisement: 3000 BDT/min
        - Wedding: 2500 BDT/min
        Mention that we accept bKash and Nagad payments (50% advance or full).`,
      },
    });
    return response.text || "দুঃখিত, আমি এই মুহূর্তে উত্তর দিতে পারছি না।";
  } catch (error) {
    console.error("Gemini Error:", error);
    return "একটি ত্রুটি ঘটেছে। অনুগ্রহ করে আবার চেষ্টা করুন।";
  }
};

