const LiveSubscriberCounter = () => {
  const [subs, setSubs] = useState(YT_BASE_SUBS);

  useEffect(() => {
    const interval = setInterval(() => {
      const change = Math.random() > 0.5 ? 1 : -1;
      setSubs(prev => {
        const next = prev + change;
        // Keep it within a realistic range of the base
        if (next > YT_BASE_SUBS + 50) return prev - 1;
        if (next < YT_BASE_SUBS - 50) return prev + 1;
        return next;
      });
    }, 3000);
    return () => clearInterval(interval);
  }, []);

  return (
    <div className="flex flex-col items-center">
      <div className="flex items-center gap-1.5">
        <span className="text-xl font-black text-white">{subs.toLocaleString()}</span>
        <div className="w-2 h-2 bg-red-600 rounded-full animate-pulse shadow-[0_0_8px_red]"></div>
      </div>
      <p className="text-[10px] text-yellow-500 font-bold uppercase tracking-wider">সাবস্ক্রাইবার লাইভ</p>
    </div>
  );
};

