const YT_LIVE_BASE = 124676;

const LiveSubscriberCounter = () => {
  const [subs, setSubs] = useState(YT_LIVE_BASE);

  useEffect(() => {
    const interval = setInterval(() => {
      const change = Math.random() > 0.5 ? 1 : -1;
      setSubs(prev => {
        const next = prev + change;
        if (next > 124999) return prev - 1;
        if (next < 124001) return prev + 1;
        return next;
      });
    }, 2500);
    return () => clearInterval(interval);
  }, []);

  return (
    <div className="flex flex-col items-center">
      <div className="flex items-center gap-2">
        <span className="text-2xl font-black text-white tabular-nums tracking-tighter">{subs.toLocaleString()}</span>
        <div className="w-2.5 h-2.5 bg-red-600 rounded-full animate-pulse shadow-[0_0_12px_red]"></div>
      </div>
      <p className="text-[11px] text-yellow-500 font-bold uppercase tracking-[0.2em] mt-1">YouTube Live Count</p>
    </div>
  );
};

