import React, { useState, useEffect } from 'react';
import { createRoot } from 'react-dom/client';
import { 
  PRICING_PLANS, 
  SONG_PLANS,
  CONTACT_NUMBER, 
  YT_BASE_SUBS,
  YT_CHANNEL_NAME, 
  YT_CHANNEL_URL, 
  YT_PROFILE_PIC,
  PORTFOLIO_VIDEOS,
  SOCIAL_LINKS,
  LIVE_ACTIVITIES
} from './constants';
