  return (
    <div className="fixed top-28 left-1/2 -translate-x-1/2 z-[60] w-[92%] pointer-events-none">
      <div className="bg-slate-950/80 backdrop-blur-3xl border border-yellow-500/40 px-6 py-4 rounded-[2rem] shadow-[0_20px_50px_rgba(0,0,0,0.5)] flex items-center gap-4 animate-slide-down">
