const LiveSubscriberCounter = () => {
  const [subs, setSubs] = useState(YT_BASE_SUBS);

  useEffect(() => {
    const interval = setInterval(() => {
      const change = Math.random() > 0.5 ? 1 : -1;
      setSubs(prev => {
        const next = prev + change;
        if (next > YT_BASE_SUBS + 50) return prev - 1;
        if (next < YT_BASE_SUBS - 50) return prev + 1;
        return next;
      });
    }, 2500);
    return () => clearInterval(interval);
  }, []);

  return (
    <div className="flex flex-col items-center">
      <div className="flex items-center gap-2">
        <span className="text-3xl font-black text-white tabular-nums tracking-tighter drop-shadow-[0_0_10px_rgba(255,255,255,0.3)]">{subs.toLocaleString()}</span>
        <div className="w-3 h-3 bg-red-600 rounded-full animate-pulse shadow-[0_0_15px_red]"></div>
      </div>
      <p className="text-[11px] text-yellow-500 font-bold uppercase tracking-[0.3em] mt-1 opacity-80">YouTube Live Stats</p>
    </div>
  );
};

const FloatingTools = () => {
  // Layer 1: Ring formation around the logo
  const ringParticles = [
    { icon: '✂️', angle: 0, radius: 100 },
    { icon: '🎥', angle: 45, radius: 105 },
    { icon: '🎬', angle: 90, radius: 100 },
    { icon: '🎵', angle: 135, radius: 105 },
    { icon: '🎞️', angle: 180, radius: 100 },
    { icon: '📸', angle: 225, radius: 105 },
    { icon: '⚡', angle: 270, radius: 100 },
    { icon: '💎', angle: 315, radius: 105 },
  ];

  // Layer 2: Spread background particles
  const spreadParticles = [
    { icon: '✨', top: '5%', left: '10%' },
    { icon: '⭐', top: '15%', left: '85%' },
    { icon: '🔥', top: '80%', left: '5%' },
    { icon: '🚀', top: '85%', left: '90%' },
    { icon: '💫', top: '40%', left: '95%' },
    { icon: '🌟', top: '50%', left: '5%' },
  ];

  return (
    <div className="absolute inset-0 pointer-events-none overflow-visible">
      {/* Ring Particles */}
      <div className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 w-0 h-0 animate-spin-slow">
        {ringParticles.map((p, i) => {
          const x = Math.cos((p.angle * Math.PI) / 180) * p.radius;
          const y = Math.sin((p.angle * Math.PI) / 180) * p.radius;
          return (
            <div 
              key={`ring-${i}`}
              className="absolute text-2xl opacity-40 hover:opacity-100 transition-opacity"
              style={{ transform: `translate(${x}px, ${y}px)` }}
            >
              {p.icon}
            </div>
          );
        })}
      </div>

      {/* Spread Particles */}
      {spreadParticles.map((p, i) => (
        <div 
          key={`spread-${i}`}
          className={`absolute text-2xl opacity-20 animate-float-tool-${i % 6}`}
          style={{ top: p.top, left: p.left }}
        >
          {p.icon}
        </div>
      ))}
    </div>
  );
};

