const OrbitingParticles = () => {
  const orbits = [
    { icon: '✂️', duration: '12s', delay: '0s', radius: 80 },
    { icon: '🎥', duration: '15s', delay: '-3s', radius: 90 },
    { icon: '🎬', duration: '18s', delay: '-6s', radius: 80 },
    { icon: '🎵', duration: '20s', delay: '-9s', radius: 90 },
    { icon: '🎞️', duration: '14s', delay: '-2s', radius: 85 },
    { icon: '📸', duration: '16s', delay: '-5s', radius: 75 },
  ];

  const stars = Array.from({ length: 20 }).map((_, i) => ({
    top: `${Math.random() * 100}%`,
    left: `${Math.random() * 100}%`,
    delay: `${Math.random() * 5}s`,
    size: Math.random() * 2 + 1,
  }));

  return (
    <div className="absolute inset-0 pointer-events-none overflow-visible">
      {stars.map((star, i) => (
        <div 
          key={`star-${i}`}
          className="absolute bg-white rounded-full opacity-40 animate-pulse"
          style={{ 
            top: star.top, 
            left: star.left, 
            width: `${star.size}px`, 
            height: `${star.size}px`,
            animationDelay: star.delay 
          }}
        />
      ))}
      <div className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2">
        {orbits.map((p, i) => (
          <div 
            key={`orbit-${i}`}
            className="absolute flex items-center justify-center"
            style={{ 
              animation: `orbit-rotate ${p.duration} linear infinite`,
              animationDelay: p.delay,
              width: `${p.radius * 2}px`,
              height: `${p.radius * 2}px`,
            }}
          >
            <div className="text-xl opacity-80 drop-shadow-lg" style={{ transform: 'rotate(0deg)', marginLeft: `${p.radius * 2}px` }}>{p.icon}</div>
          </div>
        ))}
      </div>
    </div>
  );
};

