const LiveSubscriberCounter = () => {
  const [subs, setSubs] = useState(YT_BASE_SUBS);

  useEffect(() => {
    const interval = setInterval(() => {
      const change = Math.random() > 0.5 ? 1 : -1;
      setSubs(prev => {
        const next = prev + change;
        if (next > YT_BASE_SUBS + 50) return prev - 1;
        if (next < YT_BASE_SUBS - 50) return prev + 1;
        return next;
      });
    }, 2500);
    return () => clearInterval(interval);
  }, []);

  return (
    <div className="flex flex-col items-center">
      <div className="flex items-center gap-2">
        <span className="text-2xl font-black text-white tabular-nums drop-shadow-[0_0_8px_rgba(255,255,255,0.3)]">{subs.toLocaleString()}</span>
        <div className="w-2.5 h-2.5 bg-red-600 rounded-full animate-pulse shadow-[0_0_12px_red]"></div>
      </div>
      <p className="text-[9px] text-yellow-500 font-bold uppercase tracking-[0.2em] mt-0.5 opacity-80">Live YouTube Stats</p>
    </div>
  );
};

const OrbitingParticles = () => {
  const orbits = [
    { icon: '✂️', duration: '12s', radius: 80, animation: 'orbit-rotate' },
    { icon: '🎥', duration: '15s', radius: 95, animation: 'orbit-reverse' },
    { icon: '🎬', duration: '18s', radius: 85, animation: 'orbit-rotate' },
    { icon: '🎵', duration: '20s', radius: 100, animation: 'orbit-reverse' },
    { icon: '🎞️', duration: '14s', radius: 90, animation: 'orbit-rotate' },
    { icon: '📸', duration: '16s', radius: 80, animation: 'orbit-reverse' },
    { icon: '✨', duration: '8s', radius: 70, animation: 'orbit-rotate' },
    { icon: '🚀', duration: '25s', radius: 110, animation: 'orbit-reverse' },
  ];

  const stars = Array.from({ length: 25 }).map((_, i) => ({
    top: `${Math.random() * 100}%`,
    left: `${Math.random() * 100}%`,
    delay: `${Math.random() * 5}s`,
    size: Math.random() * 2 + 1,
  }));

  return (
    <div className="absolute inset-0 pointer-events-none overflow-visible">
      {stars.map((star, i) => (
        <div 
          key={`star-${i}`}
          className="absolute bg-white rounded-full opacity-30 animate-pulse"
          style={{ 
            top: star.top, 
            left: star.left, 
            width: `${star.size}px`, 
            height: `${star.size}px`,
            animationDelay: star.delay 
          }}
        />
      ))}
      <div className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2">
        {orbits.map((p, i) => (
          <div 
            key={`orbit-${i}`}
            className="absolute flex items-center justify-center"
            style={{ 
              animation: `${p.animation} ${p.duration} linear infinite`,
              width: `${p.radius * 2}px`,
              height: `${p.radius * 2}px`,
            }}
          >
            <div className="text-xl opacity-80 drop-shadow-lg" style={{ transform: 'rotate(0deg)', marginLeft: `${p.radius * 2}px` }}>{p.icon}</div>
          </div>
        ))}
      </div>
    </div>
  );
};

