const NotificationTicker = () => {
  const shuffledActivities = useMemo(() => [...LIVE_ACTIVITIES].sort(() => Math.random() - 0.5), []);
  const [index, setIndex] = useState(0);

  useEffect(() => {
    const timer = setInterval(() => setIndex(prev => (prev + 1) % shuffledActivities.length), 4500);
    return () => clearInterval(timer);
  }, [shuffledActivities]);

  return (
    <div className="fixed top-24 left-1/2 -translate-x-1/2 z-[60] w-[94%] pointer-events-none">
      <div className="bg-slate-950/98 backdrop-blur-3xl border border-yellow-500/50 px-6 py-3.5 rounded-2xl shadow-[0_20px_60px_rgba(0,0,0,0.8)] flex items-center gap-3.5 animate-slide-down">
        <div className="w-2.5 h-2.5 bg-yellow-500 rounded-full animate-ping shadow-[0_0_10px_yellow]"></div>
        <p className="text-[12px] font-black text-white truncate drop-shadow-lg tracking-wide uppercase">{shuffledActivities[index]}</p>
      </div>
    </div>
  );
};

