const NotificationTicker = () => {
  const [shuffled, setShuffled] = useState([...LIVE_ACTIVITIES]);
  const [index, setIndex] = useState(0);

  useEffect(() => {
    const timer = setInterval(() => {
      setIndex(prev => {
        const next = (prev + 1) % shuffled.length;
        if (next === 0) setShuffled([...LIVE_ACTIVITIES].sort(() => Math.random() - 0.5));
        return next;
      });
    }, 5000);
    return () => clearInterval(timer);
  }, [shuffled]);

  return (
    <div className="fixed top-[110px] left-1/2 -translate-x-1/2 z-[100] w-[90%] pointer-events-none">
      <div className="bg-slate-950/95 backdrop-blur-3xl border-2 border-yellow-500/40 px-6 py-3 rounded-2xl shadow-2xl flex items-center gap-3 animate-slide-down">
        <div className="w-2.5 h-2.5 bg-yellow-500 rounded-full animate-ping"></div>
        <p className="text-[11px] font-black text-white truncate uppercase tracking-normal">{shuffled[index]}</p>
      </div>
    </div>
  );
};

