      </div>
      <p className="text-[10px] text-yellow-500 font-bold uppercase mt-1 opacity-90 tracking-normal">Live Community Active</p>
    </div>
  );
};

const GracefulParticles = () => {
  const particles = useMemo(() => Array.from({ length: 18 }).map((_, i) => ({
    icon: ['✂️', '🎥', '🎬', '🎵', '🎞️', '📸', '✨', '🚀', '🔥'][i % 9],
    duration: `${20 + Math.random() * 30}s`,
    delay: `${Math.random() * -20}s`,
    top: `${Math.random() * 100}%`,
    left: `${Math.random() * 100}%`,
    size: 15 + Math.random() * 10,
  })), []);

  return (
    <div className="absolute inset-0 pointer-events-none overflow-hidden">
      {particles.map((p, i) => (
        <div 
          key={i}
          className="absolute animate-float-graceful opacity-40 text-white"
          style={{ 
            top: p.top, 
            left: p.left, 
            fontSize: `${p.size}px`,
            animationDuration: p.duration,
            animationDelay: p.delay
          }}
        >
          {p.icon}
        </div>
      ))}
    </div>
  );
};

