const NotificationTicker = () => {
  const [shuffled, setShuffled] = useState(() => [...LIVE_ACTIVITIES].sort(() => Math.random() - 0.5));
  const [index, setIndex] = useState(0);

  useEffect(() => {
    const timer = setInterval(() => {
      setIndex(prev => {
        const next = (prev + 1) % shuffled.length;
        if (next === 0) setShuffled([...LIVE_ACTIVITIES].sort(() => Math.random() - 0.5));
        return next;
      });
    }, 5500);
    return () => clearInterval(timer);
  }, [shuffled]);

  return (
    <div className="bg-slate-950/98 backdrop-blur-3xl border-2 border-yellow-500/50 px-6 py-3.5 rounded-2xl shadow-2xl flex items-center gap-4 animate-slide-down mx-auto w-[92%] my-4 pointer-events-none sticky top-24 z-[100]">
      <div className="w-2.5 h-2.5 bg-yellow-500 rounded-full animate-ping"></div>
      <p className="text-[12px] font-black text-white truncate uppercase tracking-tight">{shuffled[index]}</p>
    </div>
  );
};

const App: React.FC = () => {
