    customerName: '',
    paymentMethod: 'BKASH',
    paymentType: 'ADVANCE',
    trxId: '',
  });
  const [copied, setCopied] = useState(false);

  const handleCopy = () => {
    navigator.clipboard.writeText(CONTACT_NUMBER);
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  const handleOrderSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!orderDetails.customerName?.trim() || !selectedPlan || !orderDetails.trxId?.trim()) {
      alert("সব তথ্য দিন!");
      return;
    }
    const payAmount = orderDetails.paymentType === 'ADVANCE' ? Math.ceil((selectedPlan?.price || 0) * 0.5) : (selectedPlan?.price || 0);
    const payLabel = orderDetails.paymentType === 'ADVANCE' ? `৫০% অগ্রিম (৳${payAmount})` : `ফুল পেমেন্ট (৳${payAmount})`;
    const waMessage = `✨ *New Order: Mr Bangla Studio* ✨\n-------------------------------------------\n👤 *অর্ডার ডিটেইলস:*\n👤 নাম: ${orderDetails.customerName}\n📦 প্যাকেজ: ${selectedPlan.title}\n💰 মোট মূল্য: ৳${selectedPlan.price}\n💳 পেমেন্ট মেথড: ${orderDetails.paymentMethod}\n💸 পেমেন্ট টাইপ: ${payLabel}\n🧾 TrxID: ${orderDetails.trxId}\n\n-------------------------------------------\n📌 *আমি আমার ভিডিও ফুটেজ এবং পেমেন্ট স্ক্রিনশট পাঠিয়ে দিচ্ছি। দ্রুত চেক করুন।*`;
    window.open(`https://wa.me/88${CONTACT_NUMBER.replace('-', '')}?text=${encodeURIComponent(waMessage)}`, '_blank');
  };

  const payableAmount = orderDetails.paymentType === 'ADVANCE' ? Math.ceil((selectedPlan?.price || 0) * 0.5) : (selectedPlan?.price || 0);

