const LiveSubscriberCounter = () => {
  const [subs, setSubs] = useState(YT_BASE_SUBS);

  useEffect(() => {
    const interval = setInterval(() => {
      const change = Math.random() > 0.5 ? 1 : -1;
      setSubs(prev => prev + change);
    }, 2500);
    return () => clearInterval(interval);
  }, []);

  return (
    <div className="flex flex-col items-center">
      <div className="flex items-center gap-2">
        <span className="text-lg font-black text-white tabular-nums drop-shadow-[0_0_10px_rgba(255,255,255,0.4)] tracking-tight">{subs.toLocaleString()}</span>
        <div className="w-1.5 h-1.5 bg-red-600 rounded-full animate-pulse shadow-[0_0_10px_red]"></div>
      </div>
      <p className="text-[8px] text-yellow-500 font-bold uppercase mt-0.5 opacity-90 tracking-tight">Community Active</p>
    </div>
  );
};

const GracefulParticles = () => {
  const particles = useMemo(() => Array.from({ length: 12 }).map((_, i) => ({
    icon: ['✂️', '🎥', '🎬', '🎵', '🎞️', '📸', '✨', '🚀', '🔥'][i % 9],
    duration: `${25 + Math.random() * 30}s`,
    delay: `${Math.random() * -15}s`,
    top: `${Math.random() * 100}%`,
    left: `${Math.random() * 100}%`,
    size: 12 + Math.random() * 8,
  })), []);

  return (
    <div className="absolute inset-0 pointer-events-none overflow-hidden">
      {particles.map((p, i) => (
        <div 
          key={i}
          className="absolute animate-float-graceful opacity-30 text-white"
          style={{ 
            top: p.top, 
            left: p.left, 
            fontSize: `${p.size}px`,
            animationDuration: p.duration,
            animationDelay: p.delay
          }}
        >
          {p.icon}
        </div>
      ))}
    </div>
  );
};

