const NotificationTicker = () => {
  const [shuffled, setShuffled] = useState(() => [...LIVE_ACTIVITIES].sort(() => Math.random() - 0.5));
  const [index, setIndex] = useState(0);

  useEffect(() => {
    const timer = setInterval(() => {
      setIndex(prev => {
        const next = (prev + 1) % shuffled.length;
        if (next === 0) setShuffled([...LIVE_ACTIVITIES].sort(() => Math.random() - 0.5));
        return next;
      });
    }, 5500);
    return () => clearInterval(timer);
  }, [shuffled]);

  return (
    <div className="px-4 py-1">
      <div className="bg-slate-950/80 backdrop-blur-2xl border border-yellow-500/30 px-3 py-2 rounded-xl shadow-lg flex items-center gap-2 animate-slide-down pointer-events-none">
        <div className="w-1.5 h-1.5 bg-yellow-500 rounded-full animate-ping"></div>
        <p className="text-[9px] font-black text-white truncate uppercase tracking-tight">{shuffled[index]}</p>
      </div>
    </div>
  );
};

