const GracefulParticles = () => {
  const particles = useMemo(() => Array.from({ length: 14 }).map((_, i) => ({
    icon: ['✂️', '🎥', '🎬', '🎵', '🎞️', '📸', '✨', '🚀', '🔥'][i % 9],
