const NotificationTicker = () => {
  const [shuffled, setShuffled] = useState(() => [...LIVE_ACTIVITIES].sort(() => Math.random() - 0.5));
  const [index, setIndex] = useState(0);

  useEffect(() => {
    const timer = setInterval(() => {
      setIndex(prev => {
        const next = (prev + 1) % shuffled.length;
        if (next === 0) setShuffled([...LIVE_ACTIVITIES].sort(() => Math.random() - 0.5));
        return next;
      });
    }, 5500);
    return () => clearInterval(timer);
  }, [shuffled]);

  return (
    <div className="px-4 py-1.5 mb-1 sticky top-[52px] z-[140]">
      <div className="bg-slate-950/85 backdrop-blur-3xl border border-yellow-500/40 px-3 py-2.5 rounded-xl shadow-2xl flex items-center gap-2 animate-slide-down pointer-events-none">
        <div className="w-1.5 h-1.5 bg-yellow-500 rounded-full animate-ping shadow-[0_0_8px_rgba(234,179,8,0.8)]"></div>
        <p className="text-[9px] font-black text-white truncate uppercase tracking-tight leading-none">{shuffled[index]}</p>
      </div>
    </div>
  );
};

